{
is_shown_when_inactive = { c:SHU ?= this has_variable = ywc_v03_initialized NOT = { has_variable = ywc_v03_shu_v03_shu_fiscal_register_settled } }
possible = { c:SHU ?= this has_variable = ywc_v03_initialized ywc_v03_has_capacity = yes ywc_shu_v03_unsettled = yes ywc_shu_v03_has_candidate_state = yes }
immediate = { ywc_v03_claim_arc_shu_v03_shu_fiscal_register = yes ywc_shu_open_register_once = yes set_variable = { name = ywc_shu_blocked_12_due days = 365 } set_variable = { name = ywc_shu_blocked_36_due days = 1095 } set_variable = { name = ywc_shu_pending_event value = 1000 } }
on_fail = { ywc_shu_close_as_breach = yes }
on_monthly_pulse = {
 effect = {
 if = { limit = { has_variable = ywc_shu_v03_pilot_state NOT = { ywc_shu_v03_has_pilot_state = yes } NOT = { var:ywc_shu_pilot_state_lost = 1 } } set_variable = { name = ywc_shu_pilot_state_lost value = 1 } if = { limit = { has_variable = ywc_shu_pending_event } set_variable = { name = ywc_shu_resume_event value = var:ywc_shu_pending_event } remove_variable = ywc_shu_pending_event } else_if = { limit = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event = 1 } set_variable = { name = ywc_shu_resume_event value = 1001 } } else_if = { limit = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event = 2 } set_variable = { name = ywc_shu_resume_event value = 1002 } } else_if = { limit = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event = 3 } set_variable = { name = ywc_shu_resume_event value = 1003 } } else_if = { limit = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event = 4 } if = { limit = { OR = { has_variable = ywc_shu_military_payer has_variable = ywc_shu_military_advance_paid } } set_variable = { name = ywc_shu_resume_event value = 1004 } } else = { set_variable = { name = ywc_shu_resume_event value = 1003 } } } else_if = { limit = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event = 5 } set_variable = { name = ywc_shu_resume_event value = 1005 } } else_if = { limit = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event = 6 } if = { limit = { OR = { has_variable = ywc_shu_merchant_advance has_variable = ywc_shu_merchant_advance_unpaid has_variable = ywc_shu_merchant_advance_repaid has_variable = ywc_shu_merchant_advance_refused has_variable = ywc_shu_merchant_advance_narrowed } } set_variable = { name = ywc_shu_resume_event value = 1006 } } else = { set_variable = { name = ywc_shu_resume_event value = 1005 } } } else = { set_variable = { name = ywc_shu_resume_event value = 1001 } } set_variable = { name = ywc_shu_pending_event value = 1001 } }
 if = { limit = { has_variable = ywc_shu_waiting_for_capacity NOT = { has_variable = ywc_shu_first_audit } ywc_shu_v03_real_execution_ready = yes NOT = { has_variable = ywc_shu_pending_event } } set_variable = { name = ywc_shu_pending_event value = 1001 } }
 if = { limit = { NOT = { has_variable = ywc_shu_first_audit } has_variable = ywc_shu_waiting_for_capacity NOT = { has_variable = ywc_shu_blocked_12_due } NOT = { has_variable = ywc_shu_blocked_12_notice } NOT = { has_variable = ywc_shu_pending_event } } set_variable = { name = ywc_shu_pending_event value = 1001 } }
 if = { limit = { NOT = { has_variable = ywc_shu_register_pilot_resolved } NOT = { has_variable = ywc_shu_blocked_36_due } NOT = { has_variable = ywc_shu_blocked_36_prompted } NOT = { has_variable = ywc_shu_pending_event } OR = { AND = { NOT = { has_variable = ywc_shu_first_audit } has_variable = ywc_shu_waiting_for_capacity NOT = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event ?= 6 } } var:ywc_v03_shu_v03_shu_fiscal_register_last_event >= 7 AND = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event ?= 6 OR = { has_variable = ywc_shu_merchant_advance has_variable = ywc_shu_merchant_advance_unpaid has_variable = ywc_shu_merchant_advance_repaid has_variable = ywc_shu_merchant_advance_refused has_variable = ywc_shu_merchant_advance_narrowed } } } } set_variable = { name = ywc_shu_blocked_36_months value = 1 } set_variable = { name = ywc_shu_pending_event value = 1006 } }
 if = { limit = { has_variable = ywc_shu_first_audit NOT = { has_variable = ywc_shu_second_audit } NOT = { has_variable = ywc_shu_second_audit_due } NOT = { has_variable = ywc_shu_pending_event } OR = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event >= 7 AND = { var:ywc_v03_shu_v03_shu_fiscal_register_last_event ?= 6 OR = { has_variable = ywc_shu_merchant_advance has_variable = ywc_shu_merchant_advance_unpaid has_variable = ywc_shu_merchant_advance_repaid has_variable = ywc_shu_merchant_advance_refused has_variable = ywc_shu_merchant_advance_narrowed } } } } set_variable = { name = ywc_shu_pending_event value = 1006 } }
 if = { limit = { ywc_v03_can_deliver_major = yes var:ywc_shu_pending_event = 1000 } remove_variable = ywc_shu_pending_event trigger_event = { id = ywc_shu.1000 } }
 else_if = { limit = { ywc_v03_can_deliver_major = yes var:ywc_shu_pending_event = 1001 } remove_variable = ywc_shu_pending_event remove_variable = ywc_shu_waiting_for_capacity trigger_event = { id = ywc_shu.1001 } }
 else_if = { limit = { ywc_v03_can_deliver_major = yes var:ywc_shu_pending_event = 1002 } remove_variable = ywc_shu_pending_event trigger_event = { id = ywc_shu.1002 } }
 else_if = { limit = { ywc_v03_can_deliver_major = yes var:ywc_shu_pending_event = 1003 } remove_variable = ywc_shu_pending_event trigger_event = { id = ywc_shu.1003 } }
 else_if = { limit = { ywc_v03_can_deliver_major = yes var:ywc_shu_pending_event = 1004 } remove_variable = ywc_shu_pending_event trigger_event = { id = ywc_shu.1004 } }
 else_if = { limit = { ywc_v03_can_deliver_major = yes var:ywc_shu_pending_event = 1005 } remove_variable = ywc_shu_pending_event trigger_event = { id = ywc_shu.1005 } }
 else_if = { limit = { ywc_v03_can_deliver_major = yes var:ywc_shu_pending_event = 1006 } remove_variable = ywc_shu_pending_event trigger_event = { id = ywc_shu.1006 } }

 }
}
}

