 if = { limit = { has_variable = ywc_shu_settlement_review NOT = { has_variable = ywc_shu_settlement_review_due } has_variable = ywc_shu_settlement_review_mature NOT = { has_variable = ywc_shu_review_interrupted } NOT = { has_variable = ywc_shu_pending_event } } set_variable = { name = ywc_shu_pending_event value = 1008 } }
 if = { limit = { ywc_v03_can_deliver_major = yes var:ywc_shu_pending_event = 1007 } remove_variable = ywc_shu_pending_event trigger_event = { id = ywc_shu.1007 } }
